#pragma once
static void hydrogenLabelCheck(const std::string& dir){
    using namespace r62;using namespace core;using namespace integration;
    auto require=[](bool ok,const char* why){if(!ok)throw std::runtime_error(why);};
    struct Example{int element;const char* label;int hydrogens;};
    std::vector<Example> examples={{8,"OH",1},{8,"HO",1},{7,"NH",1},{7,"NH2",2},{7,"H2N",2},{7,"NH₂",2},{16,"SH",1},{16,"HS",1},{6,"CH3",3},{14,"SiH3",3}};
    auto verify=[&](Session& s,ObjectId atom,const std::string& raw,bool left){RingGeometry rings(s.doc);auto labels=molecular::labels(s.doc,s.glyphs,rings);require(labels.count(atom),"hydride label rendered");const auto& l=labels.at(atom);auto gs=l.layout.glyphs;bool prefix=false;size_t chars=0;require(molecular::hydrideLabel(s.doc.atoms().get(atom)->element,raw,&prefix,&chars),"hydride parsed");size_t isotope=s.doc.atoms().get(atom)->semantics.isotope?std::to_string(s.doc.atoms().get(atom)->semantics.isotope).size():0;size_t total=0;for(auto g:gs)if(g.codepoint=='+'||g.codepoint==0x2212)++total;size_t base=gs.size()-isotope-total,e0=isotope+(prefix?base-chars:0),e1=e0+chars,h0=isotope+(prefix?0:chars),h1=prefix?e0:isotope+base;
        double ex=(gs[e0].x+gs[e1-1].x+gs[e1-1].advance)*.5+l.layout.anchor.x,hx=(gs[h0].x+gs[h1-1].x+gs[h1-1].advance)*.5+l.layout.anchor.x;require(std::abs(ex-s.doc.atoms().get(atom)->position.x)<1e-7,"bond endpoint stays on the heavy element");require(left?hx<ex:hx>ex,"hydrogen lies away from neighbouring bond");
        for(auto bid:s.doc.incidentBonds(atom)){auto bond=s.doc.bonds().get(bid);auto data=rings.build(*bond);molecular::clip(data,*bond,labels,1.6);require(!data.shapes.empty(),"label does not hide entire bond");for(const auto& shape:data.shapes)if(shape.points.size()==2)require(length(shape.points[1]-shape.points[0])>s.doc.defaultBondLength()*.42,"visible bond reaches heavy element with normal clearance");}
    };
    int checks=0;std::vector<std::shared_ptr<Session>> gallery;
    for(auto example:examples)for(auto font:{"Arial","Times New Roman"})for(auto direction:std::vector<Vec2>{{-1,0},{1,0},{-.866,-.5},{-.866,.5},{.866,-.5},{.866,.5},{0,-1},{0,1}}){
        auto source=std::make_shared<Session>();auto& s=*source;s.doc.setDefaultFont(font);s.doc.setDefaultBondLength(30);ObjectId middle,atom,bond;require(s.doc.addAtom(Vec2(),6,&middle).ok()&&s.doc.addAtom(direction*30,example.element,&atom).ok()&&s.doc.addBond(middle,atom,&bond).ok(),"hydride fixture");auto sem=s.doc.atoms().get(atom)->semantics;sem.implicitHydrogens=example.hydrogens;sem.showLabel=true;s.doc.setAtomSemantics(atom,sem);s.doc.setAtomLabel(atom,example.label);TextRun run;run.utf8=example.label;run.fontName=font;run.size=10;run.flags=kFormula;studioatom::set(s.doc,atom,{run});auto before=s.doc.digest();verify(s,atom,example.label,direction.x<0);require(s.doc.digest()==before,"layout preserves label, graph, hydrogen count and styles");++checks;
        if(std::string(example.label)=="NH2"&&std::string(font)=="Arial"&&direction.x<-.8&&direction.y>.1){sem.charge=1;sem.isotope=15;s.doc.setAtomSemantics(atom,sem);verify(s,atom,"NH2",true);auto& ext=s.doc.extensions(ObjectRef(ObjectKind::Atom,atom));ext.set("studio.label.offset","1 4");ext.set("studio.label.text","NH2");verify(s,atom,"NH2",true);sem.charge=0;sem.isotope=0;s.doc.setAtomSemantics(atom,sem);ext.erase("studio.label.offset");ext.erase("studio.label.text");}
        if(std::string(font)=="Arial"&&direction.x<-.8&&direction.y>.1&&(std::string(example.label)=="OH"||std::string(example.label)=="NH2"||std::string(example.label)=="SH")){
            auto path=dir+"/"+example.label;s.refresh();require(s.save(path+".t01doc",false).ok()&&s.save(path+".cdxml",true).ok(),"save hydride fixture");for(auto suffix:{".t01doc",".cdxml"}){Session back;require(back.open(path+suffix).ok(),"reopen hydride fixture");for(const auto& a:back.doc.atoms().records())if(a.isAlive()&&a.element==example.element)verify(back,a.id,example.label,true);}gallery.push_back(source);
            // A rotated or mirrored structure must update without rewriting its label.
            auto pos=s.doc.atoms().get(atom)->position;require(s.doc.setAtomPosition(atom,Vec2(-pos.x,pos.y)).ok(),"mirror hydride position");verify(s,atom,example.label,false);s.doc.setAtomPosition(atom,pos);
        }
    }
    // The same rule applies to pyrrolic NH atoms with two bonds, such as the
    // right-hand NH in the new porphyrin templates.
    for(int sign:{-1,1}){Session s;ObjectId n,a,b,ab,bb;s.doc.setDefaultBondLength(30);s.doc.addAtom(Vec2(),7,&n);s.doc.addAtom(Vec2(sign*26,15),6,&a);s.doc.addAtom(Vec2(sign*26,-15),6,&b);s.doc.addBond(n,a,&ab);s.doc.addBond(n,b,&bb);s.doc.setAtomLabel(n,"NH");verify(s,n,"NH",sign>0);}
    for(int sign:{-1,0,1}){Session s;ObjectId n,a,b,ab,bb;s.doc.addAtom(Vec2(),7,&n);s.doc.addAtom(Vec2(-26,sign*15),6,&a);s.doc.addAtom(Vec2(26,sign*15),6,&b);s.doc.addBond(n,a,&ab);s.doc.addBond(n,b,&bb);s.doc.setAtomLabel(n,"NH");RingGeometry rings(s.doc);auto labels=molecular::labels(s.doc,s.glyphs,rings);auto& gs=labels.at(n).layout.glyphs;require(sign<0?gs[1].y>gs[0].y:gs[1].y<gs[0].y,"two-sided NH uses open vertical gap");for(auto id:{ab,bb}){auto bond=s.doc.bonds().get(id);auto data=rings.build(*bond);molecular::clip(data,*bond,labels,1.6);require(!data.shapes.empty()&&length(data.shapes[0].points[1]-data.shapes[0].points[0])>20,"stacked NH preserves both visible bonds");}}
    for(auto direction:std::vector<Vec2>{{-1,0},{1,0},{-.866,-.5},{-.866,.5},{.866,-.5},{.866,.5},{0,-1},{0,1}}){Session s;ObjectId c,n,b;s.doc.setDefaultBondLength(30);s.doc.addAtom(Vec2(),6,&c);s.doc.addAtom(direction*30,7,&n);BondRecord bond;bond.beginAtom=c;bond.endAtom=n;bond.order=BondOrder::Double;s.doc.addBondRecord(bond,&b);auto sem=s.doc.atoms().get(n)->semantics;sem.implicitHydrogens=1;s.doc.setAtomSemantics(n,sem);s.doc.setAtomLabel(n,"NH");verify(s,n,"NH",direction.x<0);}
    bool first=false;size_t chars=0;for(auto name:{"Ph","Me","Boc","COOH","NHCOCH3"})require(!molecular::hydrideLabel(6,name,&first,&chars),"unrelated aliases are not reversed");
    // Reproduce the supplied left-facing phenol with an intact aromatic ring.
    auto phenol=std::make_shared<Session>();phenol->activateCommand("chooseRingTool_Benzene");phenol->gesture(PointerPhase::Down,Vec2(),0);phenol->gesture(PointerPhase::Up,Vec2(),0);ObjectId attached=kInvalidObjectId;Vec2 best(1e9,0);for(const auto& a:phenol->doc.atoms().records())if(a.isAlive()&&a.position.x<best.x){attached=a.id;best=a.position;}ObjectId oxygen,bond;phenol->doc.addAtom(best+Vec2(-12.4708,7.2),8,&oxygen);phenol->doc.addBond(attached,oxygen,&bond);auto sem=phenol->doc.atoms().get(oxygen)->semantics;sem.implicitHydrogens=1;phenol->doc.setAtomSemantics(oxygen,sem);phenol->doc.setAtomLabel(oxygen,"O");phenol->doc.extensions(ObjectRef(ObjectKind::Atom,oxygen)).set("studio.hydrogens.manual","1");phenol->refresh();verify(*phenol,oxygen,"OH",true);require(phenol->save(dir+"/phenol.t01doc",false).ok(),"save phenol");gallery.insert(gallery.begin(),phenol);
    Bitmap sheet(1200,310,PixelFormat32bppARGB);Graphics g(&sheet);g.SetPageUnit(UnitPixel);g.SetSmoothingMode(SmoothingModeAntiAlias);g.Clear(white);for(size_t i=0;i<gallery.size();++i){auto source=std::make_shared<Session>();source->doc=gallery[i]->doc;source->doc.setDefaultBondLength(4.0);source->refresh();TemplateThumbnail thumb(source);thumb.paint(g,RectF(float(i)*300+12,20,276,230));const char* names[]={"苯酚 · HO 朝外","羟基 · HO","氨基 · H₂N","巯基 · HS"};txt(g,names[i],RectF(float(i)*300,270,300,30),16,ink,true,true);}
    UINT count=0,bytes=0;GetImageEncodersSize(&count,&bytes);std::vector<uint8_t> storage(bytes);auto codecs=(ImageCodecInfo*)storage.data();GetImageEncoders(count,bytes,codecs);for(UINT i=0;i<count;++i)if(wcscmp(codecs[i].MimeType,L"image/png")==0)require(sheet.Save(W(dir+"/hydrogen-labels.png").c_str(),&codecs[i].Clsid,0)==Ok,"save hydrogen label preview");
    std::ofstream(dir+"/hydrogen-label-checks.json")<<"{\"direction_font_label_cases\":"<<checks<<",\"element_anchoring\":true,\"bond_clearance\":true,\"styles_and_semantics_preserved\":true,\"isotope_and_charge\":true,\"imported_offsets\":true,\"mirror_updates\":true,\"two_bond_NH\":true,\"double_bond_directions\":8,\"native_cdxml_roundtrip\":true,\"phenol\":true}";
}
